  UPDATE news_items SET headline = $nh$Локалитет Беловоде код Петровца на Млави furnaces: earliest secure copper smelting evidence worldwide, dated to 4900 BC$nh$, summary = $ns$Локалитет Беловоде код Петровца на Млави furnaces: earliest secure copper smelting evidence worldwide, dated to 4900 BC. Excavations at Локалитет Беловоде код Петровца на Млави and Pločnik led by archaeometallurgist Miljana Radivojević uncovered copper slag, malachite beads, and metal droplets in Vinča-period contexts Results confirmed through chemical and microstructural analysis, published in a 2021 monograph Pushed back confirmed date of true copper smelting to 4900 BC, making Локалитет Беловоде код Петровца на Млави the earliest secure evidence of extractive metallurgy anywhere in the world$ns$, post_text = $np$Archaeometallurgist Miljana Radivojević's excavations at Локалитет Беловоде код Петровца на Млави and Pločnik uncovered copper slag, malachite beads, and metal droplets in Vinča-period layers, confirmed by chemical and microstructural analysis published in a 2010 Journal of Archaeological Science paper. This pushes confirmed copper smelting to c. 5000 BC, making Локалитет Беловоде код Петровца на Млави the earliest secure evidence of extractive metallurgy in Europe. Rudna Glava is one of the earliest known copper mines, mined at scale. Incredible! 🔥⚒️$np$, facts = $nf$["Excavations at Локалитет Беловоде код Петровца на Млави and Pločnik led by archaeometallurgist Miljana Radivojević uncovered copper slag, malachite beads, and metal droplets in Vinča-period contexts", "Results confirmed through chemical and microstructural analysis, published in a 2021 monograph", "Pushed back confirmed date of true copper smelting to 4900 BC, making Локалитет Беловоде код Петровца на Млави the earliest secure evidence of extractive metallurgy anywhere in the world", "Miners specifically favored black and green copper ores, reflecting deliberate cultural aesthetic preferences", "Rudnik Glava identified as one of the earliest known copper mines, mined at scale", "Tin bronze foil recovered at Pločnik dated to ~4650 BC, over 1,000 years before the Bronze Age, but the tradition was short-lived", "Copper mostly used for ornaments and status display, not replacing stone tools"]$nf$::jsonb WHERE id = 8351 AND headline = $oh$Belovode furnaces: earliest secure copper smelting evidence worldwide, dated to 4900 BC$oh$ AND summary = $os$Belovode furnaces: earliest secure copper smelting evidence worldwide, dated to 4900 BC. Excavations at Belovode and Pločnik led by archaeometallurgist Miljana Radivojević uncovered copper slag, malachite beads, and metal droplets in Vinča-period contexts Results confirmed through chemical and microstructural analysis, published in a 2021 monograph Pushed back confirmed date of true copper smelting to 4900 BC, making Belovode the earliest secure evidence of extractive metallurgy anywhere in the world$os$ AND post_text = $op$Archaeometallurgist Miljana Radivojević's excavations at Belovode and Pločnik uncovered copper slag, malachite beads, and metal droplets in Vinča-period layers, confirmed by chemical and microstructural analysis published in a 2010 Journal of Archaeological Science paper. This pushes confirmed copper smelting to c. 5000 BC, making Belovode the earliest secure evidence of extractive metallurgy in Europe. Rudna Glava is one of the earliest known copper mines, mined at scale. Incredible! 🔥⚒️$op$ AND facts = $of$["Excavations at Belovode and Pločnik led by archaeometallurgist Miljana Radivojević uncovered copper slag, malachite beads, and metal droplets in Vinča-period contexts", "Results confirmed through chemical and microstructural analysis, published in a 2021 monograph", "Pushed back confirmed date of true copper smelting to 4900 BC, making Belovode the earliest secure evidence of extractive metallurgy anywhere in the world", "Miners specifically favored black and green copper ores, reflecting deliberate cultural aesthetic preferences", "Rudnik Glava identified as one of the earliest known copper mines, mined at scale", "Tin bronze foil recovered at Pločnik dated to ~4650 BC, over 1,000 years before the Bronze Age, but the tradition was short-lived", "Copper mostly used for ornaments and status display, not replacing stone tools"]$of$::jsonb;
  GET DIAGNOSTICS n = ROW_COUNT;
