  UPDATE news_items SET headline = $nh$China's 大汶口遗址公园 holds oldest elongated skulls claimed at 10,000 years old$nh$, summary = $ns$China's 大汶口遗址公园 holds oldest elongated skulls claimed at 10,000 years old. Host claims Dàrén Cùyū (Darren Cuyu) in China contains the oldest known elongated skulls, dated to approximately 10,000 years ago Host notes the site's top level was excavated first, meaning all archaeologists have passed through the oldest strata Host criticizes archaeological methodology of finding later-period artifacts in lower levels at this site$ns$, post_text = $np$The oldest known elongated skulls in China date to approximately 12,000 years ago, not 10,000. The site name "Dàrén Cùyū (Darren Cuyu)" does not correspond to any verified archaeological site in available records, and the elongated skulls from this period are not associated with 大汶口遗址公园 culture, which dates to roughly 4,300–2,600 BCE. Claims about excavation methodology causing later artifacts to appear in lower strata remain unverified.$np$ WHERE id = 8359 AND headline = $oh$China's Dawenkou holds oldest elongated skulls claimed at 10,000 years old$oh$ AND summary = $os$China's Dawenkou holds oldest elongated skulls claimed at 10,000 years old. Host claims Dàrén Cùyū (Darren Cuyu) in China contains the oldest known elongated skulls, dated to approximately 10,000 years ago Host notes the site's top level was excavated first, meaning all archaeologists have passed through the oldest strata Host criticizes archaeological methodology of finding later-period artifacts in lower levels at this site$os$ AND post_text = $op$The oldest known elongated skulls in China date to approximately 12,000 years ago, not 10,000. The site name "Dàrén Cùyū (Darren Cuyu)" does not correspond to any verified archaeological site in available records, and the elongated skulls from this period are not associated with Dawenkou culture, which dates to roughly 4,300–2,600 BCE. Claims about excavation methodology causing later artifacts to appear in lower strata remain unverified.$op$ AND facts = $of$["Host claims Dàrén Cùyū (Darren Cuyu) in China contains the oldest known elongated skulls, dated to approximately 10,000 years ago", "Host notes the site's top level was excavated first, meaning all archaeologists have passed through the oldest strata", "Host criticizes archaeological methodology of finding later-period artifacts in lower levels at this site", "Host argues this discovery pattern reflects excavation order, not chronological anomalies"]$of$::jsonb;
  GET DIAGNOSTICS n = ROW_COUNT;
